mapper.update:

UPDATE inbox_event
SET status = 'PROCESSED',
    processed_at = #{processedAt},
    last_error = NULL,
    updated_at = #{processedAt}
WHERE event_id = #{eventId}
  AND consumer_name = #{consumerName}


UPDATE inbox_event
SET status = 'FAILED',
    last_error = #{lastError},
    updated_at = NOW()
WHERE event_id = #{eventId}
  AND consumer_name = #{consumerName}
